package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamShanthikarmaBank2 {
    private const val T = "දේශීය ශාන්තිකර්ම හා යාතුකර්ම"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("කොහොඹා කංකාරියේ පුරාවෘත්තය අනුව පඬුවස්දෙව් රජුගේ සිහිනයෙන් පෙනුණු භයානක සත්වයා කවුද?", "දිවියෙකු (කොටියෙකු)", "මොනරෙකු", "සමනලයෙකු", "මත්ස්‍යයෙකු", "කුවේණියගේ ශාපය නිසා දිවියෙකු පනිනු සිහිනයෙන් දැක රජු රෝගාතුර විය."),
        q("කොහොඹා කංකාරියේදී මලය රජුගේ සොහොයුරන් දෙදෙනා හඳුන්වනු ලබන නම් මොනවාද?", "කිත්සිරි සහ සඳසිරි", "ජසයා සහ ලෙන්චිනා", "රාම සහ ලක්ෂ්මණ", "විජය සහ සුමිත්ත", "මලය රජු, කිත්සිරි සහ සඳසිරි යන තිදෙනා ලක්දිවට පැමිණ පළමු කංකාරිය පැවැත්වූහ."),
        q("බලි ශාන්තිකර්මයේදී 'බලි' යන වචනයෙන් අදහස් කරන මූලික අර්ථය කුමක්ද?", "පූජාව හෙවත් ග්‍රහයන් උදෙසා පිදෙන උපහාරය", "බලහත්කාරයෙන් කරන රාජ සභා නියෝගය", "ගොයම් කැපීමෙන් පසු පවත්වන කමත් ක්‍රීඩාව", "පෙරහැරේ ගමන් මාර්ගය සරසන ධජ පතාක පෙළ", "ග්‍රහ දේවතාවුන් සතුටු කිරීමට සාදන මැටි රූප හා පූජාවන් බලි නමින් හැඳින්වේ."),
        q("රට යකුම ශාන්තිකර්මයේදී ආතුර කාන්තාවට සෙත් පැතීම සඳහා යොදාගන්නා 'දොළහ පාලිය' තුළ දැකිය හැකි කොටසක් කුමක්ද?", "සළු පාලිය, කෙණ්ඩි පාලිය සහ කළස් පාලිය", "සන්නි දහඅට", "කෝලම් පෙළපාලිය", "ලී කෙළි පෙළපාලිය", "පිරිසිදු කිරීමේ හා ආශිර්වාද ගෙන ඒමේ පාලි නැටුම් රට යකුමේදී ඉදිරිපත් කෙරේ."),
        q("දේශීය ශාන්තිකර්මවල 'යහන් දැක්ම' යනුවෙන් හඳුන්වන්නේ කුමන අවස්ථාවද?", "මල් යහන් වෙත දෙවියන් ආරාධනා කර පූජා දැක්වීමේ කොටස", "යාගය අවසානයේ ආතුරයා නින්දට පිටත් කර යැවීමේ කොටස", "ශාන්තිකර්මය නිම වී මඩුව හා තොරණ ගලවා දැමීමේ කොටස", "සියලු බෙර වාදනය නවතා නිහඬව සිටීමේ විවේක අවස්ථාව", "දෙවියන් වැඩම කරවීම සඳහා ගැයෙන යාතිකා හා නැටුම් යහන් දැක්මට අයත් වේ."),
        q("කොහොඹා කංකාරියේදී 'දන්වැට පාලිය' ඉදිරිපත් කරන නැට්ටුවා අතේ ගෙන යන පූජා උපකරණය කුමක්ද?", "දැල්වූ පන්දම් හෙවත් දන්වැට", "කඩුව", "මැටි කළය", "රබාන", "සුදු පන්දම් වැටි දල්වා දුම්මල ගසමින් දෙවි ආශිර්වාදය පැතීම මෙහිදී සිදු වේ."),
        q("පහතරට 'දෙවොල් මඩුවේදී' සිදු කරන 'තොරණ පැදකුණු කිරීම' හෙවත් 'දේවාල බැලීම' මගින් ඉටු වන්නේ කුමක්ද?", "දෙවිවරුන්ගේ රූප හා තොරණට ගෞරව දැක්වීම", "තොරණ බිම හෙළීම", "පන්දම් නිවා දැමීම", "නැටුමෙන් ඉවත් වීම", "තෙල්මේ නැට්ටුවන් තොරණ ඉදිරිපිට නටමින් දේව ගෞරවය දක්වයි."),
        q("දහඅට සන්නියේදී සන්නි යකුන් මඩුවට පැමිණීමෙන් පසු පළමුව සිදු කරන සිරිත කුමක්ද?", "සභාපති හෙවත් බෙරකරු සමඟ හාස්‍යජනක දෙබස් කීම හා පිදේනි ඉල්ලීම", "ආතුරයා දෙස නොබලාම නිහඬව මඩුවෙන් පිටව යාම", "යක් බෙරය පසෙක තබා උඩරට ගැටබෙර වාදනය කිරීම", "වන්නම් දහඅටේම කවි හා තානම් පිළිවෙළින් ගායනය", "සන්නි යකුන් පිදේනි ගෙන ආතුරයාගේ රෝගය අතහැර යන බවට පොරොන්දු වේ."),
        q("ශාන්තිකර්ම මඩුවක 'මල් බුලත් තටුව' මත සාමාන්‍යයෙන් තැන්පත් නොකරන ද්‍රව්‍යය කුමක්ද?", "මස් හා මත්පැන්", "සුදු මල් හා බුලත් කොළ", "පුවක් මල් හා හඳුන් කූරු", "පහන් හා පඬුරු", "දේව හා බුදු පූජා සඳහා පිවිතුරු සාත්වික ද්‍රව්‍ය පමණක් මල් බුලත් තටුවේ තබයි."),
        q("උඩරට 'කොහොඹා කංකාරියේදී' රඟ දක්වන 'ගුරුගේ මාලාව' හෝ 'මලය උපත' මගින් කියැවෙන්නේ කුමක්ද?", "මලය රජුගේ උපත හා ලක්දිවට වැඩම කිරීමේ පුවත", "විජය රජුගේ ගමන", "පහතරට සන්නි උපත", "සබරගමු සමන් දෙවි උපත", "සීතා දේවියගේ දරුවන් ලෙස මලය රජු ඇතුළු සොහොයුරන් උපන් පුවත කංකාරියේ ගැයේ."),
        q("ශාන්තිකර්මයකදී 'කප් සිටුවීම' යන චාරිත්‍රය සිදු කරන්නේ කුමන දිනයකද?", "ශාන්තිකර්මයට දින කිහිපයකට පෙර ශුභ නැකතින්", "ශාන්තිකර්මය අවසන් වී දින හතකට පසු", "අවමංගල්‍ය දිනයේදී", "නැකැත් නොබලා ඕනෑම රාත්‍රියක", "මඩුව ඉදිකිරීමේ ආරම්භය හා දෙවියන්ට භාර වීම කප් සිටුවීමෙන් සිදු කෙරේ."),
        q("සබරගමු 'පහන් මඩුවේදී' පත්තිනි මෑණියන් උදෙසා පූජා කරන 'සළඹ' රැගෙන නැටීම හඳුන්වන්නේ කෙසේද?", "සළඹ නැටුම හෙවත් හළඹ සැලීම", "කඩු නැටුම", "කෝලම් නැටුම", "සන්නි නැටුම", "පත්තිනි දේවියගේ පූජනීය සළඹ සොලවමින් ආශිර්වාද කිරීම මෙහිදී සිදු වේ."),
        q("පහතරට 'මහ සොහොන් සමයමේදී' නැට්ටුවා 'පැදුරක දිගා වී' රඟ දක්වන අවස්ථාව හඳුන්වන්නේ කුමන නමකින්ද?", "මළ යකා හෙවත් අවමංගල්‍ය සංකේත රංගනය", "සිංහරාජ වන්නම", "ගොයම් කැපීම", "කළගෙඩි නැටුම", "ආතුරයා වෙනුවෙන් මරණ බිය යකාට පවරා ආතුරයා බේරා ගැනීම මෙයින් සංකේතවත් කෙරේ."),
        q("බලි ශාන්තිකර්මයේදී 'බලි රූපය' තැනීමෙන් පසු ආතුරයාට පෙනෙන සේ එය තැන්පත් කරන්නේ කොතැනද?", "ආතුරයා ඉදිරිපිට උස් මැස්සක් මත", "නිවස පිටුපස කළුවර කාමරයක", "වහලයට ඉහළින්", "පොළොව යට වළක", "ග්‍රහ දේවතාවුන්ගේ රූප දෙස බලා සිටීමෙන් රෝගියාට මානසික ශක්තිය ලැබේ."),
        q("ශාන්තිකර්මයකදී 'දුම්මල' ලබා ගනු ලබන්නේ කුමන ශාක මාධ්‍යයකින්ද?", "හල් හෝ දුන් ගස්වලින් ලබා ගන්නා වියළි මැලියම් (රෙසින්)", "වියළි පොල් ලෙලි කුඩු හා දහයියා මිශ්‍රණය", "කෙටූ වී පොතු කුඩු හා තිරිඟු පිටි මිශ්‍රණය", "අමු කහ අල වියළා සාදා ගන්නා කහ කුඩු", "ගිනි දැල්ලට ගැසූ විට ක්ෂණිකව දැල්වී සුවඳ දුම් විහිදුවන ස්වාභාවික මැලියම් වර්ගයකි."),
        q("උඩරට 'වලියක් මංගල්‍යය' ඉදිරිපත් කිරීමේදී නැට්ටුවන් අඳින ඇඳුම කුමක්ද?", "සාමාන්‍ය වෙස් ඇඳුම නොව කඩු, පන්දම් හා විශේෂ හිස් වැසුම් සහිත වලියක් ඇඳුම", "පහතරට කෝලම් නාට්‍යයේ මහ සම්මත රජ ඇඳුම හා ඔටුන්න", "සාමාන්‍ය පාසල් සෞන්දර්ය නර්තන සුදු නිල ඇඳුම", "පහතරට දෙවොල් මඩුවේ තෙල්මේ නැට්ටුවන්ගේ රතු තොප්පිය", "දළදා පෙරහැරේ දෝෂ දුරු කරන වලියක් මංගල්‍යයට ආවේණික පිළිවෙත් පවතී."),
        q("පහතරට 'රට යකුම' තුළ කළු යකාගේ චරිතය හා රිද්දි බිසවුන් අතර සිදුවන කථා පුවත මඟින් ඉස්මතු වන්නේ කුමක්ද?", "දරු සෙනෙහස, මාතෘ ආරක්ෂාව හා සමාජ සාරධර්ම", "රාජ සභා නඩු තීන්දු හා දඬුවම්", "යුද බිමේ සතුරු සටන් හා ජයග්‍රහණ", "සාගර තරණය හා නාවික වෙස් ගැන්වීම්", "ගැබිනි මවකගේ මානසික සුවතාව හා දරු පිළිසිඳ ගැනීම කලාත්මකව නිරූපණය වේ."),
        q("දේශීය ශාන්තිකර්මයක 'කන්නලව්ව' යනුවෙන් හඳුන්වන්නේ කුමන අංගයද?", "දෙවියන්ගේ ගුණ කියා ආතුරයාගේ දුක පවසා පිහිට පැතීම", "බෙර වාදනය නතර කර මඩුවෙන් බැහැරවීම", "ප්‍රේක්ෂකයන් හාස්‍යයෙන් සිනහ ගැන්වීම", "තොරණේ ගොක් කොළ සැරසිලි කඩා දැමීම", "හැඟීම්බර හා ගෞරවනීය හඬකින් දෙවියන්ට ආයාචනා කිරීම කන්නලව්වයි."),
        q("ශාන්තිකර්ම මඩුවේ 'තෙල් මල්' පූජාවෙන් පසු යකැදුරා සිදු කරන 'වස් දොස් හැරීම' සඳහා බහුලව භාවිත කරන පලතුර හෝ ගෙඩිය කුමක්ද?", "දෙහි ගෙඩිය හෝ පොල් ගෙඩිය", "අඹ කොළ අත්ත", "බුලත් කොළය", "සඳුන් කැබැල්ල", "දෙහි කැපීම හා පොල් ගැසීම දෝෂ ඉවත් කිරීමේ සංකේතාත්මක චාරිත්‍ර වේ."),
        q("කොහොඹා කංකාරියේදී 'ගුරු බුලත්' දීම හා 'මඩු පූජාව' අතර ඇති සම්බන්ධය කුමක්ද?", "විද්වත් ගුරුවරුන් හා දෙවියන් පිදීමෙන් යාගයට අවසර ලබා ගැනීම", "යාග මඩුවේ උස ප්‍රමාණය මැන ලකුණු කර ගැනීම", "නැටුම් පොත් ප්‍රේක්ෂක පිරිස අතර බෙදා දීම", "තරගකාරී නැටුම් අංගවල ලකුණු ගණනය කිරීම", "පූර්ව ආචාර චාරිත්‍ර ඉටු නොකර කිසිදු ශාන්තිකර්මයක් ආරම්භ නොකරයි."),
        q("දහඅට සන්නියේදී 'ගොළු සන්නිය' වේදිකාවට පැමිණි විට ප්‍රේක්ෂකයාට සිනහව උපදවන්නේ කෙසේද?", "විකට ඉරියව්, හිස සැලීම් සහ අපැහැදිලි ශබ්ද මගින් බෙරකරු සමඟ සංවාද කිරීමෙන්", "මඩුව මැද පැය ගණනක් පුරා පුස්කොළ පොත් කියවීමෙන්", "උඩරට සම්ප්‍රදායේ උදාර වන්නම් දහඅට ගායනා කිරීමෙන්", "පන්දම් හා කඩු ගෙන ද්වන්ධ සටන් රංගනයක් දැක්වීමෙන්", "වෙස්මුහුණේ ස්වභාවයට ගැළපෙන සේ ශාරීරික අභිනයෙන් හාස්‍යය මවයි."),
        q("ශාන්තිකර්මයකදී 'කිරි ඉතිරවීම' සිදු කරනු ලබන්නේ කුමන ශුභ පැතුමක් සංකේතවත් කිරීමටද?", "සෞභාග්‍යය, සාමය හා පවිත්‍ර සශ්‍රීකත්වය උදා වීම", "යාග මඩුවේ ගොක් කොළ තොරණ ගිනි ගැනීම වැළැක්වීම", "ගමේ ජනතාව අතර පවතින බෝවන රෝග වැඩි වීම", "ශාන්තිකර්මයේ නියමිත පූජා කාලය නාස්ති වී යාම", "පහන් මඩු හා ගම්මඩුවල අවසානයේදී හෝ ආරම්භයේදී කිරි උතුරවා ආශිර්වාද ගනී."),
        q("බලි ශාන්තිකර්මයේදී ආතුරයාට ඇතිවන අපල දුරු කිරීමට බලි රූප ඉදිරියේ වාදනය කරන ප්‍රධාන වාද්‍ය භාණ්ඩය කුමක්ද?", "උඩරටදී ගැටබෙරය හා පහතරටදී යක් බෙරය සමඟ මිණි ගෙඩිය", "බටහිර සම්භාව්‍ය තත් වාද්‍ය වයලීනය හා චෙලෝව", "ලෝහ සුසිර වාද්‍ය භාණ්ඩයක් වන සැක්සෆෝනය", "නූතන විදුලි ස්වර පුවරු සහිත ඉලෙක්ට්‍රොනික් ඕගනය", "සීනු හෙවත් අත් මිණිය සොලවමින් බලි ඇදුරා කවි ගයන අතර බෙරකරු තාලය දෙයි."),
        q("පහතරට 'ගම්මඩුව' ශාන්තිකර්මයේදී 'දෙවොල් මඩුව' හා සමානව පවත්වන විශේෂ පූජාවක් කුමක්ද?", "දේව දානය හෙවත් කිරි අම්මාවරුන්ගේ දානය", "සන්නි මස් පූජාව", "කෝලම් තරගය", "බටහිර සාදය", "පත්තිනි මෑණියන් උදෙසා පිරිසිදු කිරි ආහාර පූජා කර ගමටම ආශිර්වාද ලබා ගනී."),
        q("කොහොඹා කංකාරියේදී නැට්ටුවා 'යක් ඇනුම' නටන අවස්ථාවේදී පැළඳ සිටින ඇඳුම කුමක්ද?", "සම්පූර්ණ වෙස් ඇඳුම", "කෝලම් ලී මුහුණ", "සොකරි කමත් ඇඳුම", "සාමාන්‍ය කමිසය", "වෙස් නැට්ටුවන් පෙළට සිට ගැටබෙර තාලයට යක් ඇනුම නැටීම අතිශය ගාම්භීරය."),
        q("දේශීය ශාන්තිකර්මවල 'පංච වර්ග' හෝ 'නව ධාන්‍ය' පූජාවට ගන්නේ ඇයි?", "පරිසරයේ සියලු සශ්‍රීක සම්පත් දෙවියන්ට කැප කර ආශිර්වාද පැතීමට", "අසල්වැසි ගම්මාන සමඟ හුවමාරු කර ගැනීමට", "වේදිකාවේ මල් තටුවේ බර වැඩි කර තැබීමට", "මඩුව අසලට එන කුරුල්ලන් පලවා හැරීමට", "වී, මුං, තල, කුරක්කන් ආදී ධාන්‍ය වර්ග දේව ආශිර්වාදය පිණිස තබයි."),
        q("පහතරට 'සූනියම් යාගයේදී' වඩිග පටුන නටන බමුණන් සංඛ්‍යාව සාම්ප්‍රදායිකව කී දෙනෙකු වේද?", "හත් දෙනෙකි හෝ එක් ප්‍රධාන බමුණෙකි", "සිය දෙනෙකි", "දෙදෙනෙකු පමණි", "තිස් දෙනෙකි", "වඩිග දේශයෙන් පැමිණි බමුණන්ගේ පුවත රංගගත කිරීම මෙහිදී සිදු වේ."),
        q("ශාන්තිකර්මයකදී 'පිරිත් නූල' හෙවත් 'ඇප නූල' ආතුරයාගේ අතේ බඳින්නේ කුමන අතකද?", "පිරිමින්ගේ දකුණු අතේත් කාන්තාවන්ගේ වම් අතේත් හෝ දකුණු අතේ", "ආතුරයාගේ වම් පාදයේ වළලුකරේ සිළම්බු සමඟ පමණි", "ආතුරයාගේ හිසේ මුදුනේ ජටාවක් මෙන් ගැටගසා", "ආතුරයාගේ ඉණ වටා රතු පටියක් සමඟ බැඳ පමණි", "යාගය අවසානයේ පූජනීය මන්ත්‍ර බලයෙන් ආරක්ෂාව සඳහා නූල් බඳිනු ලැබේ."),
        q("ශාන්තිකර්ම කලාව හදාරන සිසුවෙකුට එයින් ලැබෙන වැදගත්ම සංස්කෘතික අවබෝධය කුමක්ද?", "සිංහල ජනශ්‍රැතිය, සාහිත්‍යය, නාට්‍ය කලාව හා මානසික චිකිත්සාව පිළිබඳ දැනුම", "බටහිර යුද ඉතිහාසය හා සටන් උපක්‍රම පිළිබඳ පුහුණුව", "දේශීය හා විදේශීය වාස්තු විද්‍යා සැලසුම්කරණ ශිල්පය", "පැරණි කෘෂිකාර්මික වාරි තාක්ෂණය හා ජල පාලන ක්‍රමවේද", "සාම්ප්‍රදායික ශාන්තිකර්ම අපේ සංස්කෘතික විවිධත්වයේ කැඩපතකි."),
        q("සබරගමු 'පහන් මඩුව' සහ උඩරට 'කොහොඹා කංකාරිය' අතර ඇති ප්‍රධාන වෙනස්කම කුමක්ද?", "භාවිත වන ප්‍රධාන බෙරය, නර්තන ශෛලිය හා මුල් වූ දේව පුරාවෘත්තය", "එකක සංගීතයක් හා බෙර තිබී අනෙකේ කිසිවක් නොතිබීම", "එකක් ලංකාවේත් අනෙක ඉන්දියාවේත් පමණක් පැවැත්වීම", "එකක පූජා කවි හා යාතිකා ගායනා සම්පූර්ණයෙන් නොමැති වීම", "කංකාරිය මලය රජු හා ගැටබෙරය මතද, පහන් මඩුව සමන්/පත්තිනි දෙවිවරුන් හා දිගු දවුල මතද පදනම් වේ."),
        q("පහතරට 'දහඅට සන්නියේදී' සන්නි යකුන්ට ආහාර ලෙස ලබා දෙන 'පිදේනි' අතර ප්‍රධාන වශයෙන් අඩංගු වන්නේ කුමක්ද?", "බත්, කැවිලි, බුලත් පුවක් හා පලතුරු", "වේවැල් කුලු හා ලී කෝටු", "මැටි කළගෙඩි හා තාලම්පට", "පැරණි පන්දම් හා ගොක් කොළ", "ගමේ ස්වාභාවික ආහාර ද්‍රව්‍ය යොදා ගනිමින් කෙසෙල් කොළ මත පිදේනි තබයි."),
        q("ශාන්තිකර්මයක 'ගොක් කොළ කැටයම්' නිර්මාණය කරන ප්‍රධාන කොටස් මොනවාද?", "පුන්කලස්, මල් කළඹ, පහන් පැල් සහ මකර තොරණ", "පුටු සහ මේස ඇතිරිලි", "ගැල් හා කරත්ත රෝද", "පාවහන් හා ඔටුනු", "සාම්ප්‍රදායික සැරසිලි කලාවේ විශිෂ්ටත්වය ගොක් කොළ කැටයම්වලින් පෙනේ."),
        q("කොහොඹා කංකාරියේදී පැවැත්වෙන 'කුවේණි අස්න' කොටසේදී ගායනා කරන්නේ කුමන ශෝකී පුවතද?", "විජය රජු විසින් කුවේණිය හා දරුවන් පිටුවහල් කළ පුවත", "රාමායණයේ සීතා පැහැර ගැනීම", "සිදුහත් කුමරුගේ උපත", "මහින්දාගමනය", "පඬුවස්දෙව් රජුගේ රෝගයට මුල් වූ කුවේණි ශාපය මෙම අස්නෙන් පැහැදිලි කෙරේ."),
        q("දේශීය ශාන්තිකර්මයකදී 'ආශිර්වාද කවි' ගයන විට ප්‍රේක්ෂක පිරිස හා ආතුරයා අනුගමනය කළ යුතු පිළිවෙත කුමක්ද?", "සාධුකාර දෙමින් දෑත් එක් කොට ගෞරවයෙන් සවන් දීම", "උස් හඬින් කෑගසා බාධා කිරීම", "මඩුවෙන් පිටතට දිව යාම", "හිනැහෙමින් විහිළු කිරීම", "සමූහ භක්තිය හා ශ්‍රද්ධාව ශාන්තිකර්මයේ මානසික ප්‍රතිඵලය වැඩි කරයි."),
        q("පහතරට 'රට යකුමේදී' ප්‍රධාන වශයෙන් පිදුම් ලබන ගර්භණී මව්වරුන්ගේ ආරක්ෂක බලවේගය කුමක්ද?", "රිද්දි බිසවුන් හත්දෙනා සහ කළු කුමාරයා", "වැදි යක්කමේ පැමිණෙන ආදිවාසී වැදි රජු", "පුරාවෘත්තවල එන පළමු රජු වූ මහ සම්මත රජු", "ගැමි සොකරි නාටකයේ ප්‍රධාන චරිතය වන ගුරුහාමි", "දරු උපත හා මව ආරක්ෂා කිරීමේ පුරාවෘත්තය මෙම යාගයේ රඟ දැක්වේ."),
        q("ශාන්තිකර්මයක 'බෙර හඬ' මගින් මිනිස් මනසට ඇති කරන ප්‍රධාන බලපෑම කුමක්ද?", "ඒකාග්‍රතාව, උද්යෝගය හා මානසික ආතතිය පහව යාම", "අධික ශබ්දය නිසා ශ්‍රවණ ආබාධ හා කන් බිහිරි වීම", "සිත තුළ රෞද්‍ර කෝපය හා වෛරය ක්‍රමයෙන් වැඩි වීම", "නිදිමත හා අලස බව ඇති වී රංගනය අතපසු වීම", "රිද්මයානුකූල බෙර නාදය මනෝවිද්‍යාත්මක සුවයක් ගෙන දීමට උපකාරී වේ."),
        q("උඩරට, පහතරට හා සබරගමු ශාන්තිකර්ම අද වන විට වේදිකාව මත ප්‍රසංග කලාවක් ලෙස ඉදිරිපත් කිරීමේදී සිදු කරන්නේ කුමක්ද?", "පැය ගණන් පවතින යාගවල ප්‍රධාන කලාත්මක අංග කෙටි කර ප්‍රාසාංගිකව ඉදිරිපත් කිරීම", "සාම්ප්‍රදායික අංග අතහැර මුළුමනින්ම විදේශීය නැටුම් මිශ්‍ර කිරීම", "සියලු ප්‍රාදේශීය බෙර වාදනය සම්පූර්ණයෙන්ම ඉවත් කර නිහඬව රැඟීම", "පූජනීය කෝලම් හා සන්නි වෙස්මුහුණු සියල්ල වේදිකාවෙන් බැහැර කිරීම", "සාම්ප්‍රදායික අනන්‍යතාව රැකගෙන නූතන ප්‍රේක්ෂකයාට රස විඳීමට සකස් කෙරේ."),
        q("ශාන්තිකර්ම මඩුවක 'මගුල් පහන' දැල්වීම සිදු කරන්නේ කවුරුන් අතින්ද?", "ප්‍රධාන ආතුරයා හෝ යාගාචාර්යවරයා අතින් ශුභ මොහොතින්", "ගමේ කුඩා දරුවන් පමණක් විසින්", "පිටතින් යන මගීන් විසින්", "මඩුව අවසන් වූ පසුව", "සෙත් පැතීමේ කටයුත්ත ආරම්භ වන බව පොල් තෙල් පහන දැල්වීමෙන් පෙනේ."),
        q("පහතරට 'ගම්මඩුවක' දී දෙවියන්ට පූජා කරන 'මුරුතැන් බත' පිසිනු ලබන්නේ කුමන ආකාරයකින්ද?", "ඉතා පිරිසිදුව මුඛවාඩම් බැඳ නැවුම් මැටි වළඳක", "සාමාන්‍ය ගෘහස්ථ මුළුතැන්ගෙයක", "පැරණි ලී භාජනයක", "මස් මාංශ මිශ්‍ර කරමින්", "දේව පූජාවට පිසින ආහාර අතිශය පවිත්‍රතාවයෙන් සැකසීම අනිවාර්ය චාරිත්‍රයකි."),
        q("දේශීය ශාන්තිකර්ම පුහුණු වන නැට්ටුවෙකු සතු විය යුතු උසස්ම ශාරීරික ගුණාංගය කුමක්ද?", "මුළු රැයක් පුරා නොසැලී නැටීමේ දරාගැනීමේ ශක්තිය (Stamina)", "විනාඩි දෙකකින් විඩාවට පත්වීම", "බිම හිඳ සිටීම", "හඬ අඩු වීම", "සන්ධ්‍යාවේ සිට උදෑසන දක්වා යාගය ඉදිරිපත් කිරීමට ඉහළ ශාරීරික යෝග්‍යතාව අවශ්‍ය වේ."),
        q("ශාන්තිකර්ම ක්ෂේත්‍රයේ 'ගරා යකුම' පවත්වන විට ගරා යකා මඩුවේ කුමන කොටසකට නැඟ විනෝදාත්මක දේ සිදු කරයිද?", "අයිලය හෙවත් මඩුවේ උස් කණුවක් මතට (කප් ගසට)", "භූගත වළකට", "වැවක් මැදට", "වේදිකාවෙන් පිටතට", "කප් කණුව මත නැඟ ආශිර්වාද කිරීම ගරා යකුමේ සුප්‍රකට අවස්ථාවකි."),
        q("දේශීය ශාන්තිකර්මයන්හි 'මන්ත්‍ර හා කවි' වල අන්තර්ගත වන බෞද්ධ සංකල්පය කුමක්ද?", "සියලු යාග බුදුරජාණන් වහන්සේගේ අණසකට හා තෙරුවන් ගුණයට යටත් බව", "බෞද්ධ දර්ශනයට සම්පූර්ණ විරුද්ධ බව", "වෙනත් ග්‍රහලෝක වන්දනාව", "අවි ආයුධ පූජාව", "තෙරුවන් නමස්කාරයෙන් තොර කිසිදු සිංහල ශාන්තිකර්මයක් නොපවතී."),
        q("සබරගමු 'පහන් මඩුව' පැවැත්වීමේදී භාවිත කරන ප්‍රධාන පූජා ගීත වර්ගයක් කුමක්ද?", "සමන් දෙවි කවි හා පත්තිනි හෑල්ල", "ලී කෙළි සිංදු", "පෘතුගීසි බයිලා", "බටහිර ගීතිකා", "දේව ආශිර්වාදය ලබා ගැනීමට මෙම සාම්ප්‍රදායික කවි මාලා ගායනා කෙරේ."),
        q("පහතරට 'සන්නි' ශාන්තිකර්මය තුළ 'සන්නි' යන වචනයෙන් අදහස් කරන වෛද්‍යමය අර්ථය කුමක්ද?", "සන්නිපාත හෙවත් ශරීරයේ ත්‍රිදෝෂ කිපීමෙන් ඇතිවන රෝග", "සතුටුදායක උත්සව", "රාජකීය ආභරණ", "කෘෂිකාර්මික අස්වැන්න", "ආයුර්වේදයේ එන වා, පිත්, සෙම් කිපීමෙන් ඇතිවන රෝග සන්නි ලෙස හැඳින්විණි."),
        q("ශාන්තිකර්ම කලාව ජාතික උරුමයක් ලෙස අද වන විට රැකිය යුත්තේ ඇයි?", "පැරණි හෙළ සංස්කෘතිය, සාහිත්‍යය, කැටයම් හා නර්තන අනන්‍යතාව ඒ තුළ ගැබ්ව ඇති බැවින්", "එය නවීන වේදිකා ආලෝකකරණ ක්‍රමවේද පමණක් උගන්වන නිසා", "එය බටහිර සම්භාව්‍ය නර්තන භාෂාව පමණක් ප්‍රචලිත කරන නිසා", "එය ගම්මාන අතර ජවන හා පිටිය ක්‍රීඩා තරගයක් වන නිසා", "ලාංකේය ජන විඥානය හා කලා විශිෂ්ටත්වය ශාන්තිකර්ම හරහා අනාගතයට පැවරේ."),
        q("කොහොඹා කංකාරියේ පුරාවෘත්තයට අනුව 'විජය රජු' විසින් පිටුවහල් කළ කුවේණිය පැමිණි ප්‍රදේශය කුමක්ද?", "සිරිසවත්ථුපුරය හෝ ලංකාපුර යක්ෂ ගෝත්‍රික ප්‍රදේශය", "උතුරු ඉන්දියාවේ වාරණාසි", "දකුණු ඉන්දියාවේ මදුරාපුරය", "සබරගමු සමනොළ කන්ද", "සිරිසවත්ථුපුරයට ගිය කුවේණිය එහි යකුන් අතින් මිය ගිය බව ඉතිහාසයේ සඳහන් වේ."),
        q("කොහොඹා කංකාරියේදී මලය රජුගේ සොහොයුරන් තිදෙනා අතරින් ප්‍රධාන නායකයා කවුද?", "මලය රජතුමා", "සඳසිරි කුමරු", "කිත්සිරි කුමරු", "දෙවොල් කුමරු", "සීතා දේවියගේ දරුවන් ලෙස උපන් මලය රජු ලක්දිවට වැඩම කළ ප්‍රධාන රජු වේ."),
        q("පහතරට 'මඩු ශාන්තිකර්ම' ආරම්භයේදී සියලු දෙවියන්ට පූජා ආරාධනා කර ගැයෙන ආරම්භක කොටස කුමක්ද?", "දේව ආරාධනාව හා පත්තිනි යාතිකාව", "සන්නි පෙළපාලිය", "ගරා නැටුම", "කෝලම් රජ පැමිණීම", "ශාන්තිකර්ම මඩුවේ කටයුතු සාර්ථක වීමට පළමුව දේව ආශිර්වාදය අයැද සිටී."),
        q("බලි ශාන්තිකර්මයේදී 'පහළ බලි' හා 'උස් බලි' වශයෙන් රූප සැකසීමේදී පදනම් කරගන්නේ කුමක්ද?", "ආතුරයාගේ ජන්ම පත්‍රය සහ බලපා ඇති ග්‍රහ අපලයේ ස්වභාවය", "යාග මඩුවේ කප් කණුවේ උස ප්‍රමාණය", "වේදිකාවේ ඉදිරිපස පළල පමණි", "අත්වැල් ගායකයාගේ උස ප්‍රමාණය", "නව ග්‍රහ දෝෂ හා දශා අනුව ගැළපෙන බලි වර්ගය නියම කෙරේ."),
        q("රට යකුම ශාන්තිකර්මයේදී 'නැවුම් කළයක්' තබාගෙන රඟ දක්වන පාලි අංගය හඳුන්වන්නේ කුමන නමකින්ද?", "කළස් පාලිය", "පන්දම් පාලිය", "කඩු පාලිය", "සන්නි පාලිය", "දරු පිළිසිඳ ගැනීම හා මවගේ ආරක්ෂාව පතා සිදු කරන පාලි නැටුම් අතර මෙය ප්‍රධාන වේ."),
        q("දහඅට සන්නියේදී 'මරු සන්නිය' පැමිණි විට රංගනයෙන් නිරූපණය කරන්නේ කුමක්ද?", "මාරක උණ, උමතු බව සහ මරණ බිය ඇති කරන රෝග ලක්ෂණ", "මිහිරි ගීත ගායනා කිරීම", "ගොයම් කැපීම", "කළගෙඩි කරකැවීම", "බියකරු වෙස්මුහුණු පැළඳ සන්නි යකා ආතුරයාගේ රෝගී බිය ඉවත් කරයි."),
        q("ශාන්තිකර්ම මඩුවක 'බුලත් තටුව' සැකසීමේදී බුලත් කොළ තැබිය යුත්තේ කුමන පැත්තටද?", "නැට්ට යකැදුරා දෙසට හෝ සාම්ප්‍රදායික පූජා දිශාවට මුහුණලා", "නැටි කැඩුණු පරණ කොළ පමණක් තටුව මත තබා", "කිසිදු පිළිවෙළකින් තොරව අවිධිමත්ව ගොඩගසා", "කොළවල යටි පැත්ත උඩට සිටින සේ පිටුපස හරවා", "නැවුම් අග නොකැඩුණු බුලත් කොළ පූජා කටයුතු සඳහා තෝරා ගනී."),
        q("කොහොඹා කංකාරියේදී 'වැදි යක්කම' ඉදිරිපත් කරන නැට්ටුවා කථා කරන භාෂා ශෛලිය කෙබඳුද?", "ගැමි හාස්‍යජනක හා ආදිවාසී උච්චාරණ හුරු දෙබස් ශෛලියකි", "සම්පූර්ණ ඉංග්‍රීසි භාෂාව", "නිහඬ අභිනය පමණි", "සංස්කෘත ශ්ලෝක පමණි", "රාත්‍රී පුරා නිදි වරන ප්‍රේක්ෂකයන්ගේ විඩාව නිවාලීමට මෙම හාස්‍ය අංග උපකාරී වේ."),
        q("පහතරට 'සූනියම් කැපිල්ල' ශාන්තිකර්මයේදී ආතුරයා හිඳුවන විශේෂ කුටිය හඳුන්වන්නේ කුමන නමකින්ද?", "විදිය හෙවත් මඩු කුටිය (සීමා පැල)", "බලි තටුව", "අයිලය", "කෝලම් මඩුව", "ආරක්ෂිත ගොක් කොළ සීමාව තුළ ආතුරයා රඳවා යාග කටයුතු ඉටු කෙරේ."),
        q("බලි ශාන්තිකර්මයේදී 'අෂ්ට භෛරව බලිය' හෝ 'නවග්‍රහ බලිය' අවසන් වූ පසු එම රූපයට කරන්නේ කුමක්ද?", "සෙත් පතා යාගය නිම කර පිරිසිදු ස්ථානයක හෝ ගලා යන ජලය අසල තැන්පත් කිරීම", "කෞතුකාගාර ප්‍රදර්ශන මැදිරියක සදාකාලිකව තබා ආරක්ෂා කිරීම", "මඩුව අවසානයේ විශාල ගිනි මැලයක දමා සම්පූර්ණයෙන් පිළිස්සීම", "අසල්වැසි ගම්මානවල ප්‍රදර්ශන සඳහා ගැල්වලින් රැගෙන යාම", "මැටි බලි රූප තාවකාලික පූජා කලාවක් බැවින් යාගයෙන් පසු ඉවත් කෙරේ."),
        q("ශාන්තිකර්මයකදී 'මල් යහන් කවි' ගායනා කරන විට බෙර වාදනය සිදු කෙරෙන්නේ කුමන තාල ලයකින්ද?", "භක්තිමත් සෞම්‍ය මැදුම් හෝ විලම්බ ලයකින්", "අතිශය වේගවත් කෑගැසීමකින්", "කිසිදු බෙරයක් නොවැයීමෙන්", "බටහිර මාර්ච් තාලයකින්", "දෙවියන් ආරාධනා කිරීමේදී සංවර හා ගෞරවනීය වාදනයක් පවත්වා ගනී."),
        q("පහතරට 'මහ සොහොන් සමයමේ' ප්‍රධාන පූජා අංගයක් වන 'සමයම් නැටීම' සිදු කරන්නේ කුමන වේලාවන්හිදීද?", "සන්ධ්‍යාව, මැදියම් රැය සහ අලුයම යන යාම තුනේදී", "දහවල් දොළහට පමණක්", "උදෑසන නවයට පමණක්", "පැය කාලකදී පමණක්", "රාත්‍රියේ යාම තුන පුරා ක්‍රමානුකූලව ශාන්තිකර්මය ගොඩනැගේ."),
        q("දේශීය ශාන්තිකර්මයක 'ආතුර පඬුරු' ගැටගැසීම සඳහා බහුලව භාවිත කරන්නේ කුමන රෙදි කැබැල්ලක්ද?", "කහ වතුරින් තෙමූ සුදු රෙදි කැබැල්ලක්", "තද කළු පැහැති තල්පත් කැබැල්ලක්", "වර්ණවත් කඩදාසි බෑගයක්", "වියළි පන් පැදුරු පටියක්", "පිරිසිදු බව හා විෂබීජ නාශක ගුණය නිසා කහ වතුර ගැල්වූ රෙදිවල පඬුරු ගැටගසයි."),
        q("කොහොඹා කංකාරියේදී 'ඌරු යක්කම' ඉදිරිපත් කිරීමෙන් සිහිපත් කෙරෙන ඓතිහාසික සිදුවීම කුමක්ද?", "රාහු අසුරයා සූකර වෙස් ගෙන මලය රජු ලක්දිවට ගෙන්වා ගත් පුවත", "විජය රජුගේ සිංහල ජයග්‍රහණය", "දෙවොල් දෙවියන්ගේ නැව් ගමන", "පත්තිනි මෑණියන්ගේ මදුරාපුර ගමන", "පුරාවෘත්තයේ ප්‍රධාන හැරවුම් ලක්ෂ්‍යය ඌරු යක්කමෙන් නාට්‍යානුසාරයෙන් පෙන්වයි."),
        q("සබරගමු 'පහන් මඩුව' ශාන්තිකර්මයේදී 'පත්තිනි කවි' ගායනය සමඟ නටන නැට්ටුවන්ගේ හිස් වැසුම කුමක්ද?", "සුදු ජටාව හා පායිම්පත", "සන්නි වෙස්මුහුණ", "කෝලම් රජ ඔටුන්න", "බටහිර තොප්පිය", "සබරගමු නැටුම් ශිල්පීන් තම සම්ප්‍රදායික ඇඳුමින් පහන් මඩුව ඉදිරිපත් කරයි."),
        q("දේශීය ශාන්තිකර්මවල 'නවග්‍රහ පූජාව' පවත්වන විට ග්‍රහයන් සංඛ්‍යාව කීයක් පිදුම් ලබයිද?", "ග්‍රහයන් නව දෙනෙකි (රවි, චන්ද්‍ර, කුජ, බුධ, ගුරු, ශුක්‍ර, ශනි, රාහු, කේතු)", "ප්‍රධාන ග්‍රහ දේවතාවුන් දෙදෙනෙකු පමණක් පිදුම් ලබයි", "සතර දිසාවට අධිපති ග්‍රහයන් හතර දෙනෙකු පිදුම් ලබයි", "නැකැත් තරු සමූහයට අයත් ග්‍රහයන් විසි දෙනෙකු පිදුම් ලබයි", "ජ්‍යොතිෂ්‍ය විශ්වාස අනුව නවග්‍රහයන් උදෙසා බලි හා ග්‍රහ පූජා පවත්වයි."),
        q("පහතරට 'රට යකුමේදී' යකැදුරා කාන්තා වෙස් ගෙන රඟ දක්වන රිද්දි බිසවුන්ගේ කථාවෙන් ප්‍රකාශ වන්නේ කුමක්ද?", "මාතෘත්වයේ වටිනාකම සහ දරු උපතක පූජනීය බව", "යුද බිමේ රෞද්‍ර බව", "රාජ්‍ය පාලන නීති", "සාම්ප්‍රදායික මුහුදු යාත්‍රා ශිල්පය", "දරුඵල අපේක්ෂිත හා ගැබිනි මව්වරුන්ට මානසික ආරක්ෂාව මෙයින් ලබා දේ."),
        q("ශාන්තිකර්ම මඩුවක 'දුම් ඇල්ලීම' සඳහා භාවිත කරන සාම්ප්‍රදායික සුවඳ ද්‍රව්‍ය මොනවාද?", "සාම්බ්‍රානි, සුදු හඳුන් සහ දුම්මල", "පිරිසිදු ඇල් වතුර", "වියළි මැටි කුඩු", "ලුණු කුඩු", "විෂබීජ නාශනය මෙන්ම මනස සන්සුන් කරන පරිසරයක් මින් සැකසේ."),
        q("පහතරට 'ගම්මඩුව' තුළ ඉදිරිපත් කරන 'තෙල්මේ නැටුම' අයත් වන්නේ කුමන පූජා අවස්ථාවකටද?", "දෙවියන්ට ගෞරව දක්වන සමූහ දේව නර්තන අවස්ථාවට", "රෝගීන් බිය ගන්වන සන්නි අවස්ථාවට", "මළ බෙර අවස්ථාවට", "සොකරි කමත් අවස්ථාවට", "රතු තෙල්මේ තොප්පි පැළඳ සමූහයා තාලයට නැටීම ගම්මඩුවේ විචිත්‍ර අංගයකි."),
        q("උඩරට 'වලියක් මංගල්‍යය' පවත්වනු ලබන දින ගණන සාම්ප්‍රදායිකව කීයක් වේද?", "දින හතකි (7)", "එක් පැයකි", "මාස හයකි", "දින සියයකි", "ඇසළ පෙරහැර අවසන් වූ දිනයේ සිට දින හතක් පුරා මහා විෂ්ණු දේවාලයේ මෙය පවත්වයි."),
        q("ශාන්තිකර්මයකදී 'තටු පහේ පිදේනිය' හෝ 'පිදේනි තටු' පිළියෙළ කරන්නේ කවුරුන් සතුටු කිරීමටද?", "ප්‍රේත, කුම්භාණ්ඩ සහ යක්ෂ ගණයේ අමනුෂ්‍ය දෝෂ", "වෙස් නැටුමේ පැරණි ආචාර්ය පරපුර", "සබරගමු පෙරහැරේ හේවිසි වාදක පිරිස", "දේව මඩුවට රැස්වන සෙසු ගැමි නැට්ටුවන්", "පිදේනි ලබාගෙන ආතුරයා අතහැර යන ලෙස යාතිකා කිරීම සාම්ප්‍රදායික ක්‍රමයයි."),
        q("දේශීය ශාන්තිකර්මවල 'බෙර පද' සහ 'නැටුම් පද' වෙනස් වන්නේ කුමන සාධකය අනුවද?", "උඩරට, පහතරට හා සබරගමු යන ප්‍රාදේශීය සම්ප්‍රදාය අනුව", "දවසේ උෂ්ණත්වය අනුව පමණි", "මඩුවේ උස අනුව පමණි", "ආතුරයාගේ රැකියාව අනුව", "සෑම පළාතකම බෙරයට ආවේණික ශෛලියක් හා පද මාලාවක් පවතී."),
        q("කොහොඹා කංකාරියේදී 'ගුරු බුලත්' පිළිගැන්වීම මගින් සමාජයට දෙන ආදර්ශය කුමක්ද?", "වැඩිහිටියන්ට, ගුරුවරුන්ට හා විද්වතුන්ට නිසි ගෞරවය දැක්වීම", "වැඩිහිටියන් නොසලකා හැරීම", "පාරම්පරික කලාව වෙනස් කර දැමීම", "විනය නොතකා හැරීම", "පූර්ව ගරු බුහුමන් කලාකරුවන්ගේ විනය රකින උතුම් සිරිතකි."),
        q("පහතරට 'දහඅට සන්නියේදී' සන්නි චරිතයකට පෙර බෙරකරු අසන ප්‍රශ්නවලින් ප්‍රේක්ෂකයාට ලැබෙන්නේ කුමක්ද?", "චරිතයේ අනන්‍යතාව හා රෝග ලක්ෂණ හාස්‍යයෙන් වටහා ගැනීමට ඉඩක්", "නින්ද යාමට හේතුවක්", "වේදිකාවෙන් පිටව යාමට අණක්", "සරඹ අභ්‍යාසයක්", "බෙරකරු නාට්‍යයේ සම්බන්ධීකාරක ලෙස ප්‍රේක්ෂකයා හා යකා අතර සංවාද ගොඩනඟයි."),
        q("සබරගමු 'පහන් මඩුවක' දී නැට්ටුවන් අතේ පන්දම් ගෙන නටන අවස්ථාව හඳුන්වන්නේ කුමන නමකින්ද?", "පන්දම් පාලිය", "කළගෙඩි නැටුම", "ගොයම් නැටුම", "වඩිග පටුන", "පූජා අවස්ථා ආලෝකමත් කරමින් රිද්මයානුකූලව පන්දම් හරඹ දක්වයි."),
        q("දේශීය ශාන්තිකර්මවලදී 'අමු ගොක් කොළ' පමණක් සැරසිලි සඳහා භාවිත කිරීමට හේතුව කුමක්ද?", "නැවුම් බව, නම්‍යශීලී බව සහ පූජනීය පවිත්‍රතාව", "වියළී ඉක්මනින් කැඩී යාම", "රත්රන් පැහැය නිසා", "කෘමීන් ආකර්ෂණය කිරීමට", "ළපටි පොල් කොළවලින් ඉතා සියුම් කැටයම් පහසුවෙන් ගොතා ගත හැකිය."),
        q("බලි ශාන්තිකර්මයේදී 'පිරිත් නූල්' අතේ බැඳීමට පෙර බලි ඇදුරා සිදු කරන චාරිත්‍රය කුමක්ද?", "සෙත් කවි හා බලි යාතිකා ගායනා කර ආශිර්වාද ගැන්වීම", "නූල් වතුරේ තැම්බීම", "වෙස්මුහුණු පිළිස්සීම", "බෙර ගැලවීම", "මන්ත්‍ර හා සෙත් පැතීම් මගින් නූලට ආරක්ෂක බලය ආරෝපණය කරන බව විශ්වාස කෙරේ."),
        q("පහතරට 'දෙවොල් මඩුවේදී' දෙවොල් දෙවියන් මුහුදු බත් වූ පසු ලක්දිවට ගොඩ බසින විට බාධා කළ දේවිය කවුද?", "පත්තිනි දේවිය (ගිනි ජාලා හතක් මවා පරික්ෂා කළාය)", "සංගීතය හා කලාවට අධිපති සරස්වතී දේවිය", "දේව පුරාවෘත්තවල එන ශෘංගාර රසයේ රති දේවිය", "ශිව දෙවියන්ගේ බිරිඳ වන පාර්වතී හෙවත් උමා දේවිය", "දෙවොල් දෙවියන් ගිනි මැල හත පාගා පෙන්වා තම බලය ඔප්පු කළ බව ජනප්‍රවාදයේ එයි."),
        q("උඩරට 'කොහොඹා කංකාරිය' වර්තමානයේදී සම්පූර්ණයෙන් පැවැත්වීමේදී ඇති ප්‍රධානතම අභියෝගය කුමක්ද?", "පැරණි ගුරු ශිල්පීන් අඩු වීම හා අධික වියදම හා කාලය", "ගැටබෙර නොමැති වීම", "කොහොඹ ගස් නොමැති වීම", "සිංහල භාෂාව නොදැනීම", "දැවැන්ත ශාන්තිකර්මයක් වන කංකාරිය රැකගැනීමට රාජ්‍ය හා කලා ආයතන අනුග්‍රහය දක්වයි."),
        q("ශාන්තිකර්මයකදී 'කප් ගස' සඳහා බහුලව තෝරා ගනු ලබන ශාක කොටස කුමක්ද?", "කිරි ගසක් වන කොස් හෝ රුක්අත්තන හෝ පුවක් අත්තක්", "වියළි දර කැබැල්ලක්", "කෙසෙල් කොළයක්", "පිදුරු මිටියක්", "සරුසාර බව හා ශක්තිය සංකේතවත් වන කිරි ගසකින් කප් සිටුවීම සිදු කරයි."),
        q("පහතරට 'සූනියම් කැපිල්ල' යාගයේදී 'පුහුල්' කැපීමට අමතරව දෝෂ ඉවත් කිරීමට භාවිත කරන තවත් ද්‍රව්‍යයක් කුමක්ද?", "පොල් ගෙඩි බිඳීම සහ දෙහි කැපීම", "මැටි පිඟන් කැඩීම", "වීදුරු කැඩීම", "බෙර ඉරීම", "දෙහි හා පොල් මගින් අශුභ බලවේග බිඳ හෙළීම සංකේතවත් කෙරේ."),
        q("දේශීය ශාන්තිකර්මවලදී 'යකැදුරා' සහ 'අත්වැල් ගායකයන්' අතර පවතින සම්බන්ධතාව කුමක්ද?", "යකැදුරා කියන කවි හා යාතිකා අත්වැල් පිරිස රිද්මයට ගායනා කරමින් සහාය වීම", "යාගය අතරතුර එකිනෙකාට විරුද්ධව හාස්‍යජනක දෙබස් කීම", "මඩුව මැද යකැදුරා නටද්දී අත්වැල් පිරිස පැදුරුවල නිදා ගැනීම", "කන්නලව්ව අවසානයේ වාද්‍ය භාණ්ඩ හා බෙරවල සම් ගලවා දැමීම", "සමූහ ගායනය රාත්‍රී පුරා යාගයේ ජීව ගුණය රඳවා ගනී."),
        q("බලි ශාන්තිකර්මයේදී 'නිල් පැහැය' සාදා ගැනීමට අතීතයේ භාවිත කළ ස්වාභාවික ශාක මූලාශ්‍රය කුමක්ද?", "අවරි කොළ හෙවත් නිල් අවරි යුෂ", "රතු මල් පෙති", "කහ අල", "සුදු හුණු", "ගස් කොළ යුෂවලින් ස්වාභාවික වර්ණක සැකසීම දේශීය චිත්‍ර ශිල්පයේ දක්ෂතාවකි."),
        q("පහතරට 'දහඅට සන්නිය' තුළින් ප්‍රධාන වශයෙන්ම හෙළිදරව් වන සමාජ චිකිත්සක ක්‍රමය කුමක්ද?", "හාස්‍යය, නාට්‍යමය අභිනය හා මානසික නිදහස ලබා දීමෙන් රෝග සමනය", "වේදිකාව මත කෘතිම රෝගී සටන් හා පහරදීම් සිදු කිරීම", "ආතුරයාට පමණක් තනිව පන්දම් එළි අල්ලා බිය වැද්දීම", "සංගීතය හා නර්තනය නවතා රෝගියා හුදකලා කාමරයක තැබීම", "මනෝවිද්‍යාත්මක සුවය ලබා දීමේ ලාංකේය ජන කලා ක්‍රමවේදය මෙයින් පෙනේ."),
        q("ශාන්තිකර්මයක 'ආරම්භක පහන් දැල්වීම' සිදු කරන දිශාව ලෙස සාම්ප්‍රදායිකව තෝරා ගන්නේ කුමන දිශාවද?", "නැගෙනහිර හෝ උතුරු දිශාව", "අඳුරු මුල්ලක්", "බිම පොළොව යට", "වැසිකිළිය දෙසට", "හිරු උදාවන නැගෙනහිර ශුභ දිශාවක් ලෙස පෙරදිග සංස්කෘතියේ සලකයි."),
        q("සබරගමු 'පහන් මඩුවක' දී සමන් දෙවියන්ට පූජා කරන 'පහන් තිර' සාදා ගන්නේ කුමකින්ද?", "පිරිසිදු කපු පුළුන් හෝ සුදු රෙදි පටිවලින්", "කෙසෙල් නාරටි කැබලිවලින්", "යකඩ කම්බිවලින්", "කඩදාසි කැබලිවලින්", "නැවුම් පොල් තෙල් සමඟ කපු තිර දැල්වීම පිරිසිදු පූජාවකි."),
        q("උඩරට 'කොහොඹා කංකාරියේදී' නැට්ටුවන් පළඳින 'වෙස් ඇඳුම' සාමාන්‍යයෙන් පැළඳිය යුත්තේ කුමන සිරිතකින් පසුවද?", "ස්නානය කර පිරිසිදු වී තෙරුවන් හා දෙවියන් වැඳ නමස්කාර කිරීමෙන් පසුව", "පිරිසිදු වීමකින් තොරව ඕනෑම අපිරිසිදු තත්ත්වයකින් පැමිණි විට", "නර්තන මණ්ඩපය තුළ පාවහන් පැළඳගෙනම ඇවිද යාමෙන් අනතුරුව", "ශිල්පීන් අතර අනවශ්‍ය විහිළු තහළු කරමින් කාලය ගත කිරීමෙන් පසුව", "වෙස් ඇඳුම පූජනීය වස්තුවක් ලෙස සැලකීම උඩරට සම්ප්‍රදායේ අනිවාර්ය නීතියකි."),
        q("දේශීය ශාන්තිකර්මයන්හි 'තොරණ පැදකුණු කිරීම' සිදු කරන නිවැරදි දිශාව කුමක්ද?", "දක්ෂිණාවර්තව (දකුණු අත තොරණ දෙසට සිටින සේ)", "පසුපසට ඇවිදිමින්", "වක්‍රව පෙරළෙමින්", "ඉහළින් පැන", "පූජනීය ස්ථාන හා වස්තූන් දක්ෂිණාවර්තව පැදකුණු කිරීම ගෞරව චාරිත්‍රයයි."),
        q("පහතරට 'රට යකුමේදී' රිද්දි බිසවුන් නිරූපණය කරන 'වස්ත්‍ර කැටීම' කුමන කාර්යයක් සඳහා සිදු කරයිද?", "කාශ්‍යප බුදුරජාණන් වහන්සේට හෝ දෙවියන්ට සිවුරු සළු පූජා කිරීමට", "යාග මඩුවේ පිටුපස කඩතුරා වසා දැමීමට", "තොරණේ සැරසිලි හා කප් ගස වෙළා ගැනීමට", "බෙර කඳන් සහ රබන් පටල එතීම සඳහා යොදා ගැනීමට", "දරු උපතක් අපේක්ෂිත බිසවුන්ගේ පුණ්‍ය ක්‍රියාව නාට්‍යමය ලෙස මෙහි රඟ දැක්වේ."),
        q("ශාන්තිකර්ම මඩුවක 'මල් බුලත් පුටුව' අසල 'හක්ගෙඩිය' තබා පිඹීමෙන් දන්වන්නේ කුමක්ද?", "ප්‍රධාන පූජා අවස්ථාවක් ආරම්භ වන බව හා ශුභ නිමිත්ත", "ශාන්තිකර්මය වැරදුණු බව", "වැස්ස එන බව", "සියල්ලන් නින්දට යා යුතු බව", "හක්ගෙඩි හඬ පූජනීය අවස්ථා ප්‍රකාශ කරන මංගල සංඥාවයි."),
        q("බලි ශාන්තිකර්මයේදී 'බලි රූපය' මැටියෙන් අඹා නිම කිරීමට පෙර සකසන ලී සැකිල්ල කුමක්ද?", "පුවක් පටි හෝ උණ පතුරු බැඳ සකසන මූලික රාමුව", "යකඩ වෑල්ඩින් රාමුව", "වේවැල් වළලු රාමුව", "පිත්තල වාත්තු රාමුව", "පුවක් ලී රාමුව මත කෙසෙල් පතුරු බැඳ හුඹස් මැටි තවරා බලිය අඹයි."),
        q("දේශීය ශාන්තිකර්ම අතර 'හූනියම් කැපිල්ල' නමැති යාගය වඩාත් ප්‍රචලිත වී ඇත්තේ කුමන නර්තන සම්ප්‍රදායේද?", "පහතරට නර්තන සම්ප්‍රදායේ", "උඩරට වන්නම් සම්ප්‍රදායේ", "භරත නාට්‍යම් සම්ප්‍රදායේ", "කථක් සම්ප්‍රදායේ", "රුහුණු හෙවත් පහතරට සම්ප්‍රදායේ යක්ෂ හා වින කැපිලි යාග ඉතා විචිත්‍රය."),
        q("ශාන්තිකර්මයකදී 'කිරි ඉතිරවීමේ' කාර්යය සඳහා භාවිත කරන භාජනය කුමක්ද?", "අලුත් පිරිසිදු මැටි මුට්ටියක්", "පැරණි ලී කෝප්පයක්", "ලෝහ තැටියක්", "කළගෙඩියක්", "පළමු වරට භාවිතයට ගන්නා නැවුම් මැටි මුට්ටියක් ශුභ කටයුතු සඳහා තෝරා ගනී."),
        q("කොහොඹා කංකාරියේදී 'ගුරුගෙදර' කලාකරුවන් හා සිසුන් ආශ්‍රිතව රැකෙන ප්‍රධාන සමාජ බැඳීම කුමක්ද?", "ගුරු ශිෂ්‍ය ගෞරවය හා කලා පරම්පරාගත අභිමානය", "තරගකාරී අමනාපකම්", "නිහඬ පෞද්ගලික ව්‍යායාම පමණි", "කලාව සැඟවීම", "පාරම්පරික කංකාරි කලාව රැකී ඇත්තේ ශක්තිමත් ගුරු ශිෂ්‍ය සම්බන්ධතාව නිසාය."),
        q("ශාන්තිකර්මයකදී 'මඩුව අවසන් කිරීමේදී' සිදු කරන 'පින් දීම' හා 'ආශිර්වාදය' හඳුන්වන්නේ කෙසේද?", "හමාර කවි හෙවත් පින් අනුමෝදනා කවි", "ආරම්භක තානම", "යක් ඇනුම", "කප් සිටුවීම", "දෙවියන්ට, භූතයන්ට හා රැස්වූ සැමට පින් අනුමෝදන් කර යාගය සමාප්ත කෙරේ."),
        q("දේශීය ශාන්තිකර්ම පිළිබඳව ලේඛනගත වී ඇති විශේෂත්වයක් ලෙස 'නාට්‍යමය අංග' බිහි වූයේ කුමන කොටස්වලින්ද?", "දෙබස්, වෙස් ගැන්වීම් හා චරිත නිරූපණ ඇතුළත් යක්කම් හා පාලි අංගවලින්", "ඝන වාද්‍ය භාණ්ඩයක් වන තාලම්පට තැටි දෙක වැයීමෙන් පමණි", "ගොක් කොළවලින් සෙවිලි කරන ලද මඩුවේ වහලයේ සැකැස්මෙන්", "පුන්කලස් අසල එල්ලන ලද ගොක් කොළ කැටයමින් පමණි", "සිංහල ජන නාට්‍ය කලාවේ මුල් අවධිය ශාන්තිකර්ම රංගන තුළින් හඳුනාගත හැකිය."),
        q("පහතරට 'ගම්මඩුව' පැවැත්වීමෙන් ගමේ ජනතාව තුළ ඇති වන ප්‍රධාන සමාජ ප්‍රතිලාභය කුමක්ද?", "සියලු ගැමියන් එකමුතුව වැඩ කිරීමෙන් සාමය හා සහයෝගීතාව ශක්තිමත් වීම", "ගමේ පවුල් අතර අනවශ්‍ය භේද හා මතගැටුම් ඇති වීම", "ගැමියන්ගේ එදිනෙදා කෘෂිකාර්මික වගා කටයුතු අතපසු වීම", "ශාන්තිකර්මය නිසා ගමේ ස්වාභාවික සම්පත් සියල්ල විනාශ වීම", "ශාන්තිකර්ම සංවිධානය කිරීමේ සාමූහික ශ්‍රමය ගැමි එකමුතුවේ සංකේතයකි."),
        q("ශාන්තිකර්ම ක්ෂේත්‍රයේදී 'ගරා යකා' දකිනු ලබන්නේ අහිතකර බියකරු යකෙකු ලෙසද, නැතහොත් සෙත් දෙන දේවතාවෙකු ලෙසද?", "දෝෂ දුරු කර සෞභාග්‍යය ගෙනෙන යහපත් දේව ගණයට අයත් බලවේගයක් ලෙස", "සතුරු වින කරන රකුසෙකු ලෙස", "රෝග බෝ කරන යකෙකු ලෙස", "මිනිසුන්ට පහර දෙන අයෙකු ලෙස", "ගරා යකා දොළොස් ගරා ලෙස හඳුන්වන අතර සෑම යාගයකම අවසානයේ ආශිර්වාද ගෙන දේ."),
        q("ශ්‍රී ලාංකේය සාම්ප්‍රදායික ශාන්තිකර්ම හා නූතන නර්තන කලාව අතර ඇති සම්බන්ධතාව කෙටියෙන් දක්වන්න.", "නූතන වේදිකා නර්තනයේ බොහෝ පද, තාල, වෙස් ගැන්වීම් හා නාට්‍යාංග ශාන්තිකර්මවලින් පෝෂණය වී ඇත", "සාම්ප්‍රදායික ශාන්තිකර්ම හා නූතන වේදිකා නැටුම් අතර කිසිදු සම්බන්ධයක් නොමැත", "නූතන නර්තන අංග සියල්ල බටහිර බැලේ ශිල්පයෙන් පමණක් ලබාගෙන නිර්මාණය කර ඇත", "ශාන්තිකර්ම යනු පූජා විධි පමණක් වන බැවින් නර්තන කලාවට කිසිදු බලපෑමක් නොකරයි", "අපේ දේශීය නර්තන සම්ප්‍රදායන් තුනෙහිම උපත හා පැවැත්ම ශාන්තිකර්ම මත රඳා පවතී.")
    )
}

